from __future__ import annotations

from pathlib import Path


def load(path: str) -> str:
    return Path(path).read_text(encoding="utf-8")


def save(path: str, text: str) -> None:
    Path(path).write_text(text, encoding="utf-8")


def replace_once(path: str, old: str, new: str) -> None:
    text = load(path)
    count = text.count(old)
    if count != 1:
        raise RuntimeError(f"{path}: expected one replacement, found {count}: {old[:120]!r}")
    save(path, text.replace(old, new, 1))


def replace_exact(path: str, old: str, new: str, count: int) -> None:
    text = load(path)
    actual = text.count(old)
    if actual != count:
        raise RuntimeError(f"{path}: expected {count} replacements, found {actual}: {old[:120]!r}")
    save(path, text.replace(old, new))


